insert into public.changelog (title, body, category, published, published_at, created_by) values ('A mention for The Kenroe Collective', 'Added a small footer card on the sign-in landing page pointing to The Kenroe Collective — the sister event-planning platform for weddings, celebrations, and corporate gatherings. Also corrected the portfolio page''s description of the project so it accurately reflects what it is.', 'improved', true, now(), '37d308dc-56ad-4597-a3d7-b24847c466d4');